    "translation_tagged": "すると{{person:エクター|エクター卿}}は言った。「そなたはどのようにしてその剣を手に入れたのだ？」",
    "raw_tagged": "Then {{person:エクター|Sir Ector}} said, \"How came you by that sword?\"",
    "zh_tw_tagged": "於是{{person:エクター|艾克托爵士}}問道：「你是如何得到那把劍的？」",
