    "type": "本文",
    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "しばしのあいだ{{person:ケイ|ケイ卿}}は押し黙っていたが、やがて口を開いて言った。「父上、私はつい先刻戦っていたあの合戦で自分の剣を折ってしまい、その代わりにこの剣を見つけて手にしたのです。」",
    "raw_tagged": "And for a while {{person:ケイ|Sir Kay}} was silent, but after a while he said, \"Sire, I brake my sword in that battle which of late I fought, whereupon I found me this sword in its stead.\"",
    "zh_tw_tagged": "{{person:ケイ|凱爵士}}沉默了片刻，過了一會兒才說道：「父親大人，我在方才進行的那場戰鬥中折斷了自己的佩劍，於是便找來這把劍作為替代。」",
    "zh_cn_tagged": "{{person:ケイ|凯爵士}}沉默了片刻，过了一会儿才说道：“父亲大人，我在方才进行的那场战斗中折断了自己的佩剑，于是便找来这把剑作为替代。”",
    "ko_tagged": "한동안 {{person:ケイ|케이 경}}은 잠자코 있다가 얼마 뒤에 입을 열어 말했다. “아버님, 방금 치른 그 싸움에서 제 검을 부러뜨렸기에 그 대신 쓸 것으로 이 검을 구해 왔습니다.”",
    "vol_short_label_i18n": {
      "ja": "第二章 明かされた王の血統",
      "en": "Chapter II: The Royalty of Arthur Revealed",
      "zh_tw": "第二章 王室血統的揭曉",
      "zh_cn": "第二章 王室血统的揭晓",
      "ko": "제2장 밝혀진 왕의 혈통"
    }
