    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "すると{{person:エクター|エクター卿}}はあまりにも不思議なまなざしで若き{{person:アーサー|アーサー}}をじっと見つめたので、{{person:アーサー|アーサー}}はなぜそのように自分を見るのかわからなかった。そのため彼は思わず声を上げた。「父上、なぜそのような不思議な目で私をご覧になるのですか？ 私に対してお怒りなのですか？」これに{{person:エクター|エクター卿}}は答えた。「神の御前に誓って、我が息子よ、そなたに対して怒りなど抱いてはおらぬ。」それから彼は言った。「そなたがその剣を扱いたいと望むのなら、もとより心置きなくその奇跡を試してみるがよい。」",
    "raw_tagged": "Then {{person:エクター|Sir Ector}} gazed upon young {{person:アーサー|Arthur}} in such a strange manner that {{person:アーサー|Arthur}} wist not why he looked at him in that wise. Wherefore he cried out, \"Sire, why dost thou gaze so strangely upon me? Has thou anger against me?\" Whereunto {{person:エクター|Sir Ector}} made reply, \"In the sight of God, my son, I have no anger against thee.\" Then he said, \"If thou hast a desire to handle the sword, thou mayst assuredly make assay of that miracle.\"",
    "zh_tw_tagged": "這時{{person:エクター|艾克托爵士}}用一種極為奇異的目光凝視著少年{{person:アーサー|亞瑟}}，令{{person:アーサー|亞瑟}}不明白他為何那樣看著自己，便失聲喊道：「父親大人，您為何用這般異樣的眼神看著我？您是在生我的氣嗎？」對此{{person:エクター|艾克托爵士}}回答道：「在上帝面前起誓，我的兒子，我對你毫無怒意。」接著他又說：「既然你想試著擺弄這把劍，你儘管放心去嘗試那項奇蹟吧。」",
    "zh_cn_tagged": "这时{{person:エクター|艾克托爵士}}用一种极为奇异的目光凝视着少年{{person:アーサー|亚瑟}}，令{{person:アーサー|亚瑟}}不明白他为何那样看着自己，便失声喊道：“父亲大人，您为何用这般异样的眼神看着我？您是在生我的气吗？”对此{{person:エクター|艾克托爵士}}回答道：“在上帝面前起誓，我的儿子，我对你毫无怒意。”接着他又说：“既然你想试着摆弄这把剑，你尽管放心去尝试那项奇迹吧。”",
    "ko_tagged": "그러자 {{person:エクター|엑터 경}}이 너무도 기묘한 눈빛으로 어린 {{person:アーサー|아서}}를 물끄러미 바라보았으므로, {{person:アーサー|아서}}는 어찌하여 그가 자신을 그렇게 보는지 알 수 없었다. 이에 그가 소리쳤다. “아버님, 어찌하여 그리 이상한 눈빛으로 저를 바라보십니까? 제게 노여움을 품으셨습니까?” {{person:エクター|엑터 경}}이 대답했다. “하느님 앞에서 맹세코, 내 아들아, 네게는 조금도 노여운 마음이 없느니라.” 그리고 덧붙여 말했다. “네가 그 검을 다루어 보고 싶다면 틀림없이 그 기적을 시험해 보아도 좋다.”",
    "vol_short_label_i18n": {
      "ja": "第二章 明かされた王の血統",
      "en": "Chapter II: The Royalty of Arthur Revealed",
      "zh_tw": "第二章 王室血統的揭曉",
      "zh_cn": "第二章 王室血统的揭晓",
      "ko": "제2장 밝혀진 왕의 혈통"
    }
