      "en": "Part II Ch. I: Quest of the Sable Knight",
      "zh_tw": "第二部 第一章 黑騎士的挑戰",
      "zh_cn": "第二部 第一章 黑骑士的挑战",
      "ko": "제2부 제1장 검은 기사의 도전"
